// SPDX-License-Identifier: GPL-3.0

pragma solidity >=0.7.0 <0.9.0;

/**
 * @title Upload - Gasless File Sharing Contract
 * @dev A simplified contract for uploading and sharing files without gas costs for sharing
 * All files are public by default - users share via IPFS links
 */
contract Upload {

  // Store file hashes for each user
  mapping(address => string[]) public value;

  /**
   * @dev Upload a file hash to blockchain
   * @param _user The user address uploading the file
   * @param url The IPFS hash/URL of the file
   */
  function add(address _user, string memory url) external {
      value[_user].push(url);
  }

  /**
   * @dev Retrieve all files for a user (public view - no gas cost)
   * @param _user The user address to retrieve files from
   * @return Array of file URLs/hashes
   */
  function display(address _user) external view returns(string[] memory) {
      return value[_user];
  }

  /**
   * @dev Delete a file from user's collection
   * @param index The index of the file to delete
   */
  function deleteUrl(uint index) external {
    require(index < value[msg.sender].length, "Invalid index");
    for (uint i = index; i < value[msg.sender].length - 1; i++) {
      value[msg.sender][i] = value[msg.sender][i+1];
    }
    value[msg.sender].pop();
  }

  /**
   * @dev Get total number of files for a user
   * @param _user The user address
   * @return Count of files
   */
  function getFileCount(address _user) external view returns(uint) {
      return value[_user].length;
  }

  /**
   * @dev Get a specific file by index (view only - no gas)
   * @param _user The user address
   * @param index The file index
   * @return The file URL/hash
   */
  function getFile(address _user, uint index) external view returns(string memory) {
      require(index < value[_user].length, "Invalid index");
      return value[_user][index];
  }
}

